for {
	best := -1
	for v := 0; v < n; v++ {
		if !taken[v] && indegree[v] == 0 && (best < 0 || names[v] < names[best]) {
			best = v
		}
	}
	if best < 0 {
		break
	}
	order = append(order, names[best])
	taken[best] = true
}
if showCycle {
	remaining := []string{}
	for i, name := range names {
		if !taken[i] {
			remaining = append(remaining, name)
		}
	}
	sort.Strings(remaining)
	fmt.Printf("cycle: %s\n", strings.Join(remaining, " "))
